{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "header_stack",
        "chart_section_title",
        "stock_table",
        "divider_after_table",
        "view_report_button"
      ]
    },
    "header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "icon_graph",
        "main_title"
      ]
    },
    "icon_graph": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000641_01_1_graph-up-arrow.svg"
      },
      "children": []
    },
    "main_title": {
      "type": "Text",
      "props": {
        "text": "Stock Performance Comparison",
        "variant": "h2"
      },
      "children": []
    },
    "chart_section_title": {
      "type": "Text",
      "props": {
        "text": "5-Day Stock Price Trend",
        "variant": "h3"
      },
      "children": []
    },
    "stock_table": {
      "type": "Table",
      "props": {
        "title": "Company A vs. Company B Stock Performance (Past 5 Days)",
        "columns": [
          {
            "key": "Day",
            "label": "Day"
          },
          {
            "key": "Company A",
            "label": "Company A"
          },
          {
            "key": "Company B",
            "label": "Company B"
          }
        ],
        "rows": [
          {
            "Day": "Day 1",
            "Company A": 100,
            "Company B": 90
          },
          {
            "Day": "Day 2",
            "Company A": 102,
            "Company B": 91
          },
          {
            "Day": "Day 3",
            "Company A": 99,
            "Company B": 93
          },
          {
            "Day": "Day 4",
            "Company A": 105,
            "Company B": 92
          },
          {
            "Day": "Day 5",
            "Company A": 103,
            "Company B": 95
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "table",
        "primaryColumn": "Day",
        "numericColumns": ["Company A", "Company B"]
      },
      "children": []
    },
    "divider_after_table": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "view_report_button": {
      "type": "Button",
      "props": {
        "label": "View Full Report",
        "variant": "primary"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/stock-report"
          }
        }
      }
    }
  }
}
